where is_del = '0'

	AND customer_level = #{customerLevel}


	AND status = #{status}


	AND settle_type = #{settleType}


	AND (
		customer_name like concat('%', #{keyword}, '%')
		or customer_no like concat('%', #{keyword}, '%')
		or contact_name like concat('%', #{keyword}, '%')
		or contact_phone like concat('%', #{keyword}, '%')
	)


	AND create_time >= #{beginCreateTime}


	AND create_time <= #{endCreateTime}

order by create_time desc

